function stateTable=plot_ves041_behavioral_state_enrichment()
% Condense stimulus-free VES041 behavior into occupancy-normalized states.
% This function uses the 0-to-1 s post-peak and control windows generated by
% plot_ves041_spontaneous_reorientation_phase_space. The grouped prevalence
% panel shows the raw behavioral composition; the enrichment panel divides
% post-peak prevalence by control prevalence so common states are not
% mistaken for selective VES041 associations.

folder='/Users/sophiarenauld/stacks/ves041_behavior_quantification/spontaneous_reorientation_phase_space';
P=readmatrix(fullfile(folder,'pooled_peak_windows_fwd_heading.csv'));
C=readmatrix(fullfile(folder,'pooled_control_windows_fwd_heading.csv'));
names=["Low speed + small heading change";"Low-speed reorientation"; ...
    "Faster + small heading change";"Faster reorientation"];
peakMask=classify(P);controlMask=classify(C);
peakFraction=mean(peakMask,1)';controlFraction=mean(controlMask,1)';
enrichment=peakFraction./controlFraction;
stateTable=table(names,sum(peakMask,1)',sum(controlMask,1)',peakFraction, ...
    controlFraction,enrichment,'VariableNames',{'behavioralState','nPeakWindows', ...
    'nControlWindows','peakWindowFraction','controlWindowFraction','foldEnrichment'});
writetable(stateTable,fullfile(folder,'behavioral_state_enrichment.csv'));

fig=figure('Visible','off','Color','w','Position',[100 100 1250 520]);
tl=tiledlayout(fig,1,2,'TileSpacing','compact','Padding','compact');
ax=nexttile(tl);bar(ax,100*[peakFraction controlFraction]);
ylabel(ax,'Behavioral windows (%)');xticks(ax,1:4);xticklabels(ax,short_names());
legend(ax,{'After VES041 peak','Control occupancy'},'Location','northwest');
title(ax,'Behavioral composition');grid(ax,'on');
ax=nexttile(tl);b=bar(ax,enrichment,'FaceColor','flat');
b.CData=repmat([.35 .35 .35],4,1);b.CData(2,:)=[.82 .15 .12];
yline(ax,1,'k--','Expected from occupancy','HandleVisibility','off');
ylabel(ax,'Fold enrichment after VES041 peak');xticks(ax,1:4);xticklabels(ax,short_names());
title(ax,'Occupancy-normalized association');grid(ax,'on');
for i=1:4,text(ax,i,enrichment(i)+.06,sprintf('%.2fx',enrichment(i)), ...
        'HorizontalAlignment','center','FontWeight','bold');end
sgtitle(tl,'VES041 preferentially precedes low-speed reorientation, not low speed or turning alone');
savefig(fig,fullfile(folder,'behavioral_state_enrichment.fig'));
exportgraphics(fig,fullfile(folder,'behavioral_state_enrichment.png'),'Resolution',250);close(fig);
disp(stateTable);
end

function M=classify(A)
f=A(:,1);h=A(:,2);M=[f<=2 & h<30,f<=2 & h>=30,f>2 & h<30,f>2 & h>=30];
end

function n=short_names()
n={'Low + small turn','Low + reorientation','Faster + small turn','Faster + reorientation'};
end
